def get_cgroup_info(container_id, ctype, filename):
    file = f'{cgroup_base_path!s}/{ctype!s}/system.slice/docker-{container_id!s}.scope/{filename!s}'
    redata = []
    if os.path.exists(file):
        data = os.popen('cat %s' % file)
        tmp = data.readline()
        while tmp:
            redata.append(tmp[:-1])
            tmp = data.readline()
    return redata
