def get_host_mem():
    result_data = {'error_no': 0, 'error_msg': ''}
    cmdstr = 'free'
    cmd_data = os.popen(cmdstr)
    title = cmd_data.readline()
    mem_value = cmd_data.readline()
    while mem_value != '':
        if 'Mem' in mem_value:
            valist = mem_value.split()
            free_value = int(valist[3])
            if float('%.2f' % (free_value / 1048576)) < max_mem_to_stop_proc:
                result_data = {'error_no': -1, 'error_msg': '可用内存不足,请稍后再创建'}
