def check_stock_or_future(stocks):
    if isinstance(stocks, str):
        if stocks.find('SS') > -1 or stocks.find('SZ') > -1 or stocks.find('XSHE') > -1 or stocks.find('XSHG') > -1:
            return 'stock'
        elif stocks.find('CCFX') > -1 or stocks.find('XDCE') > -1 or stocks.find('XSGE') > -1 or stocks.find('XZCE') > -1:
            return 'future'
        else:
            return 'other'
    elif isinstance(stocks, list):
        stock_flag = 0
        future_flag = 0
        for stock_code in stocks:
            if not stock_code.find('SS') > -1:
                if not stock_code.find('SZ') > -1:
                    if stock_code.find('XSHE') > -1 or stock_code.find('XSHG') > -1:
                        stock_flag = 1
            if not stock_code.find('CCFX') > -1:
                if not stock_code.find('XDCE') > -1:
                    if stock_code.find('XSGE') > -1 or stock_code.find('XZCE') > -1:
                        future_flag = 1
        if stock_flag == 1 and future_flag == 0:
            return 'stock'
        elif stock_flag == 0 and future_flag == 1:
            return 'future'
        else:
            return 'other'
@unique
class FileLockException(Exception):
    pass
@unique
class FileLock(object):
    __doc__ = """ A file locking mechanism that has context-manager support so
        you can use it in a with statement. This should be relatively cross
        compatible as it doesn't rely on msvcrt or fcntl for the locking.
    """
    def __init__(self, user_id, file_name, file_path=None, timeout=10, delay=0.05):
        """ Prepare the file locker. Specify the file to lock and optionally
            the maximum timeout and the delay between each attempt to lock.
        """
        self.is_locked = False
        if file_path:
            self.lockfile = file_path
        else:
            self.lockfile = os.path.join('/dev/shm/', f'{user_id!s}.{file_name!s}.lock')
        self.file_name = file_name
        self.timeout = timeout
        self.delay = delay
    def acquire(self):
        """ Acquire the lock, if possible. If the lock is in use, it check again
            every `wait` seconds. It does this until it either gets the lock or
            exceeds `timeout` number of seconds, in which case it throws
            an exception.
        """
        start_time = time.time()
        while True:
            try:
                self.fd = os.open(self.lockfile, os.O_CREAT | os.O_EXCL | os.O_RDWR)
            except OSError as e:
                if e.errno != errno.EEXIST:
                    if os.path.exists(self.lockfile):
                        os.unlink(self.lockfile)
                    raise
                if time.time() - start_time >= self.timeout:
                    os.unlink(self.lockfile)
                    raise FileLockException('Timeout occured.')
                time.sleep(self.delay)
            else:
                break
        self.is_locked = True
        return None
    def release(self):
        """ Get rid of the lock by deleting the lockfile.
            When working in a `with` statement, this gets automatically
            called at the end.
        """
        if self.is_locked:
            os.close(self.fd)
            os.unlink(self.lockfile)
            self.is_locked = False
            return None
    def __enter__(self):
        """ Activated when used in the with statement.
            Should automatically acquire a lock to be used in the with block.
        """
        if not self.is_locked:
            self.acquire()
        return self
    def __exit__(self, type, value, traceback):
        """ Activated at the end of the with statement.
            It automatically releases the lock if it isn't locked.
        """
        if self.is_locked:
            self.release()
            return None
    def __del__(self):
        """ Make sure that the FileLock instance doesn't leave a lockfile
            lying around.
        """
        if self.is_locked:
            self.release()
            return None
def get_mem_under_oom_status(username):
    recode = {'error_no': 0, 'error_info': ''}
